      // communication, tech, immobilier, conseil-juridique, sante, alimentation, animaux, artisans, maison-deco, mode-textile, telecom, agroalimentaire, administrations, associations, bien-etre, emploi, commerce, hotellerie, batiment, automobile, finances, divertissement, autres, general
      countryCode: varchar("country_code", { length: 2 }),
      salaryMin: integer("salary_min"),
      salaryMax: integer("salary_max"),
      currency: varchar("currency").default("USD"),
