async function sendJobAlertEmail(toEmail, toName, jobs2, unsubscribeUrl) {
  const jobCount = jobs2.length;
  const subject = `\u{1F3AF} ${jobCount} new job${jobCount > 1 ? "s" : ""} matching your preferences \u2014 Verso Air`;
  const jobCards = jobs2.slice(0, 10).map(
    (job) => `
    <div class="card">
      <h3>${job.title}</h3>
      <p>${job.company} \xB7 ${job.location}</p>
      <div class="meta">
        <span class="badge">${job.type}</span>
        ${job.salary ? ` \xB7 ${job.salary}` : ""}
        \xB7 Posted ${job.postedAt}
      </div>
    </div>`
  ).join("");
  const appUrl = getAppUrl();
  const bodyHtml = `
    <p>Hi <strong>${toName}</strong>,</p>
    <p>We found <strong>${jobCount} new position${jobCount > 1 ? "s" : ""}</strong> that match your job alert preferences:</p>
    <div class="divider"></div>
    ${jobCards}
    ${jobCount > 10 ? `<p style="text-align: center; color: #888; font-size: 14px;">+ ${jobCount - 10} more positions</p>` : ""}
    <div class="divider"></div>
    <div style="text-align: center;">
      <a href="${appUrl}/services/careers" class="button">View All Jobs</a>
    </div>
    <p style="font-size: 13px; color: #888; margin-top: 20px;">\u{1F4A1} Tip: Refine your filters to get more targeted alerts.</p>
  `;
  const html = wrapInBrandedTemplate(
    "\u{1F3AF}",
    "New Job Matches",
    "linear-gradient(135deg, #2563eb 0%, #3b82f6 100%)",
    "#2563eb",
    bodyHtml,
    unsubscribeUrl
  );
  return sendEmail(toEmail, subject, html);
}
