router.get("/database/tables", async (req, res) => {
  try {
    const result = await db.execute(
      sql`
      SELECT
        t.table_name as name,
        (SELECT count(*) FROM information_schema.columns WHERE table_name = t.table_name)::int as columns,
        (SELECT count(*) FROM pg_class WHERE relname = t.table_name)::int as exists,
        t.table_type as type
      FROM information_schema.tables t
      WHERE t.table_schema = 'public'
      ORDER BY t.table_name
      `
    );
    const tablesWithStats = await Promise.all(
      result.rows.map(async (table) => {
        try {
          const stats = await db.execute(
            sql`
            SELECT
              n_live_tup::int as row_count,
              pg_total_relation_size('${sql.raw(table.name)}')/1024/1024 as size_mb
            FROM pg_stat_user_tables
            WHERE relname = ${table.name}
            LIMIT 1
            `
          );
          const stat = stats.rows[0] || {
            row_count: 0,
            size_mb: 0
          };
          const columns = await db.execute(
            sql`
            SELECT column_name, data_type, is_nullable
            FROM information_schema.columns
            WHERE table_name = ${table.name}
            ORDER BY ordinal_position
            `
          );
          return {
            name: table.name,
            displayName: table.name.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()) || table.name,
            description: `Table: ${table.name}`,
            rowCount: stat.row_count || 0,
            sizeMB: stat.size_mb || 0,
            columns: columns.rows.length,
            columnDetails: columns.rows,
            is_view: table.type === "VIEW",
            icon: table.type === "VIEW" ? "\u{1F4CB}" : "\u{1F4CA}",
            tags: [table.type === "VIEW" ? "View" : "Table", "PostgreSQL"],
            importance: stat.row_count > 1e3 ? "high" : stat.row_count > 100 ? "medium" : "low",
            hasFK: false
          };
        } catch (err) {
          console.error(`Error getting stats for table ${table.name}:`, err);
          return {
            name: table.name,
            displayName: table.name.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()) || table.name,
            description: `Table: ${table.name}`,
            rowCount: 0,
            sizeMB: 0,
            columns: 0,
            columnDetails: [],
            is_view: table.type === "VIEW",
            icon: table.type === "VIEW" ? "\u{1F4CB}" : "\u{1F4CA}",
            tags: [table.type === "VIEW" ? "View" : "Table", "PostgreSQL"],
            importance: "low",
            hasFK: false
          };
        }
      })
    );
    res.json(tablesWithStats);
  } catch (error) {
    console.error("Error fetching tables:", error);
    res.status(500).json({
      success: false,
      error: "Failed to fetch tables from PostgreSQL",
      message: error.message
    });
  }
});
router.get("/database/export", async (req, res) => {
  try {
    if (req.user?.role !== "superuser") {
      return res.status(403).json({
        success: false,
        error: "Superuser access required for data export"
      });
    }
    const { table, format: format2 } = req.query;
    if (!table || typeof table !== "string") {
      return res.status(400).json({
        success: false,
        error: "Table name is required"
      });
    }
    const tableNameRegex = /^[a-zA-Z0-9_]+$/;
    if (!tableNameRegex.test(table)) {
      return res.status(400).json({
        success: false,
        error: "Invalid table name"
      });
    }
    const result = await db.execute(sql`SELECT * FROM ${sql.raw(table)}`);
    if (format2 === "json") {
      res.setHeader("Content-Type", "application/json");
      res.setHeader(
        "Content-Disposition",
        `attachment; filename="${table}.json"`
      );
      res.json(result.rows);
    } else if (format2 === "csv") {
      const rows = result.rows;
      if (rows.length === 0) {
        res.setHeader("Content-Type", "text/csv");
        res.setHeader(
          "Content-Disposition",
          `attachment; filename="${table}.csv"`
        );
        res.send("");
        return;
      }
      const headers = Object.keys(rows[0]);
      const csvContent = [
        headers.map((h) => `"${h}"`).join(","),
        ...rows.map(
          (row) => headers.map((h) => {
            const value = row[h];
            if (value === null) return "";
            if (typeof value === "string")
              return `"${value.replace(/"/g, '""')}"`;
            return value;
          }).join(",")
        )
      ].join("\n");
      res.setHeader("Content-Type", "text/csv");
      res.setHeader(
        "Content-Disposition",
        `attachment; filename="${table}.csv"`
      );
      res.send(csvContent);
    } else {
      return res.status(400).json({
        success: false,
        error: "Unsupported format. Use 'json' or 'csv'"
      });
    }
  } catch (error) {
    console.error("Error exporting table:", error);
    res.status(500).json({
      success: false,
      error: "Failed to export table data",
      message: error.message
    });
  }
});
