// server/services/pdf-generator.ts
import PDFDocument from "pdfkit";
import fs from "fs";
import path from "path";
var UPLOADS_DIR = process.env.NODE_ENV === "production" ? path.join("/tmp", "uploads", "business-pdfs") : path.resolve("uploads", "business-pdfs");
try {
  if (!fs.existsSync(UPLOADS_DIR)) {
    fs.mkdirSync(UPLOADS_DIR, { recursive: true });
  }
} catch (err) {
  console.warn(`\u26A0\uFE0F  Could not create PDF uploads dir (${UPLOADS_DIR}):`, err);
}
async function generateBusinessPDF(data) {
  return new Promise((resolve, reject) => {
    const fileName = `business-reg-${data.id}-${Date.now()}.pdf`;
    const filePath = path.join(UPLOADS_DIR, fileName);
    const doc = new PDFDocument({ size: "A4", margin: 50 });
    const stream = fs.createWriteStream(filePath);
    doc.pipe(stream);
    const gold2 = "#bf831c";
    const darkBg2 = "#1a1a2e";
    const grey2 = "#555555";
    doc.rect(0, 0, doc.page.width, 100).fill(darkBg2);
    doc.fontSize(28).fill("#ffffff").text("Verso Air", 50, 30, { align: "left" });
    doc.fontSize(12).fill(gold2).text("Business Registration Form", 50, 65, {
      align: "left"
    });
    doc.fontSize(9).fill("#aaaaaa").text(`REF: VA-BIZ-${data.id}`, 350, 30, {
      align: "right",
      width: 195
    });
    doc.fontSize(9).fill("#aaaaaa").text(
      `Date: ${data.submittedAt ? new Date(data.submittedAt).toLocaleDateString("en-GB") : (/* @__PURE__ */ new Date()).toLocaleDateString("en-GB")}`,
      350,
      45,
      { align: "right", width: 195 }
    );
    const badgeY = 120;
    doc.roundedRect(50, badgeY, 140, 28, 4).fill("#fff3cd");
    doc.fontSize(11).fill("#856404").text("\u23F3  PENDING APPROVAL", 58, badgeY + 7, { width: 130 });
    const sectionStart = badgeY + 55;
    drawSectionTitle(doc, "Business Details", sectionStart, gold2);
    let y = sectionStart + 28;
    y = drawField(doc, "Business Name", data.name, y, grey2);
    y = drawField(doc, "Category", data.categoryName || "\u2014", y, grey2);
    y = drawField(
      doc,
      "Description",
      data.description || "No description provided",
      y,
      grey2
    );
    y += 10;
    drawSectionTitle(doc, "Location & Contact", y, gold2);
    y += 28;
    y = drawField(doc, "Address", data.address || "\u2014", y, grey2);
    y = drawField(doc, "City", data.cityName || "\u2014", y, grey2);
    y = drawField(doc, "Country", data.countryCode || "\u2014", y, grey2);
    y = drawField(doc, "Phone", data.phone || "\u2014", y, grey2);
    y = drawField(doc, "Email", data.email || "\u2014", y, grey2);
    y += 10;
    drawSectionTitle(doc, "Submission Information", y, gold2);
    y += 28;
    y = drawField(doc, "Submitted By", data.submittedBy || "Unknown", y, grey2);
    y = drawField(
      doc,
      "Submitted At",
      data.submittedAt ? new Date(data.submittedAt).toLocaleString("en-GB") : (/* @__PURE__ */ new Date()).toLocaleString("en-GB"),
      y,
      grey2
    );
    y = drawField(doc, "Reference ID", `VA-BIZ-${data.id}`, y, grey2);
    y += 20;
    doc.rect(50, y, doc.page.width - 100, 90).lineWidth(1).stroke("#dddddd");
    doc.fontSize(11).fill(darkBg2).text("Approval Decision", 60, y + 10, { underline: true });
    doc.fontSize(10).fill(grey2).text("Approved / Rejected (circle one)", 60, y + 30);
    doc.text("Approved by: ___________________________", 60, y + 50);
    doc.text("Date: _______________", 60, y + 70);
    const footerY = doc.page.height - 50;
    doc.moveTo(50, footerY - 10).lineTo(doc.page.width - 50, footerY - 10).strokeColor("#dddddd").stroke();
    doc.fontSize(8).fill("#999999").text(
      `\xA9 ${(/* @__PURE__ */ new Date()).getFullYear()} Verso Air \u2014 Business Intelligence Platform  |  This document is auto-generated and serves as a formal business registration record.`,
      50,
      footerY,
      { align: "center", width: doc.page.width - 100 }
    );
    doc.end();
    stream.on("finish", () => {
      console.log(`[PDF] Generated: ${filePath}`);
      resolve(filePath);
    });
    stream.on("error", (err) => {
      console.error("[PDF] Error generating PDF:", err);
      reject(err);
    });
  });
}
function drawSectionTitle(doc, title, y, color) {
  doc.fontSize(14).fill(color).text(title, 50, y);
  doc.moveTo(50, y + 18).lineTo(250, y + 18).strokeColor(color).lineWidth(0.5).stroke();
}
function drawField(doc, label, value, y, color) {
  doc.fontSize(10).fill(color).text(`${label}:`, 50, y, { continued: false });
  doc.fontSize(10).fill("#1a1a2e").text(value, 170, y, { width: 370, lineGap: 2 });
  const lineHeight = Math.max(
    14,
    doc.heightOfString(value, { width: 370 }) + 4
  );
  return y + lineHeight;
}

