var _bizColCache = {};
async function bizHasColumn(col) {
  if (_bizColCache[col] !== void 0 && _bizColCache[col] !== null)
    return _bizColCache[col];
  try {
    await pool.query(`SELECT ${col} FROM businesses LIMIT 0`);
    _bizColCache[col] = true;
  } catch {
    _bizColCache[col] = false;
  }
  return _bizColCache[col];
}
