router2.post(
  "/api/businesses/bulk/update",
  async (req, res) => {
    const client = await pool.connect();
    try {
      const { updates } = req.body;
      if (!Array.isArray(updates) || updates.length === 0) {
        client.release();
        return res.status(400).json({
          success: false,
          error: "Invalid bulk update format"
        });
      }
      await client.query("BEGIN");
      let updatedCount = 0;
      for (const update of updates) {
        const { id, ...data } = update;
        const setClauses = [];
        const values = [];
        let paramIndex = 1;
        for (const [key, value] of Object.entries(data)) {
          setClauses.push(`${key} = $${paramIndex}`);
          values.push(value);
          paramIndex++;
        }
        setClauses.push(`updated_at = NOW()`);
        values.push(id);
        const result = await client.query(
          `UPDATE businesses
           SET ${setClauses.join(", ")}
           WHERE id = $${paramIndex}
           RETURNING id`,
          values
        );
        if (result.rows.length > 0) updatedCount++;
      }
      await client.query("COMMIT");
      res.json({
        success: true,
        updated: updatedCount,
        message: `${updatedCount} businesses updated`
      });
    } catch (error) {
      await client.query("ROLLBACK");
      console.error("Error bulk updating businesses:", error);
      res.status(500).json({
        success: false,
        error: "Failed to bulk update businesses",
        details: error.message
      });
    } finally {
      client.release();
    }
  }
);
