var router15 = Router15();
router15.post(
  "/request",
  connectionRequestLimiter,
  async (req, res) => {
    try {
      const { fromUserId, toUserId } = req.body;
      if (!fromUserId || !toUserId) {
        return res.status(400).json({
          success: false,
          error: "fromUserId and toUserId are required"
        });
      }
      if (fromUserId === toUserId) {
        return res.status(400).json({
          success: false,
          error: "Cannot send connection request to yourself"
        });
      }
      const existingConnection = await db.select().from(connections).where(
        and9(
          eq16(connections.requesterId, fromUserId),
          eq16(connections.receiverId, toUserId)
        )
      ).limit(1);
      if (existingConnection.length > 0) {
        return res.status(400).json({
          success: false,
          error: "Connection request already exists"
        });
      }
      const [newConnection] = await db.insert(connections).values({
        requesterId: fromUserId,
        receiverId: toUserId,
        status: "pending"
      }).returning();
      const notification = await notifyConnectionRequest(fromUserId, toUserId);
      res.status(201).json({
        success: true,
        data: newConnection,
        notification,
        message: "Connection request sent successfully"
      });
    } catch (error) {
      console.error("Error sending connection request:", error);
      res.status(500).json({
        success: false,
        error: "Failed to send connection request"
      });
    }
  }
);
