router18.post("/create-checkout", async (req, res) => {
  if (!requireStripe(res)) return;
  try {
    const authenticatedUserId = req.user?.userId;
    const { targetTier, billingCycle = "monthly" } = req.body;
    if (!authenticatedUserId) {
      return res.status(401).json({ success: false, error: "Authentication required" });
    }
    if (!targetTier) {
      return res.status(400).json({ success: false, error: "targetTier is required" });
    }
    const userId = authenticatedUserId;
    const pricing = TIER_PRICING[targetTier];
    if (!pricing) {
      return res.status(400).json({
        success: false,
        error: `Invalid tier: ${targetTier}. Valid: ${Object.keys(TIER_PRICING).join(", ")}`
      });
    }
    const userResult = await pool.query(
      `SELECT id, email, username, subscription_tier FROM users WHERE id = $1`,
      [userId]
    );
    if (userResult.rows.length === 0) {
      return res.status(404).json({ success: false, error: "User not found" });
    }
    const user = userResult.rows[0];
    const amount = billingCycle === "annual" ? pricing.annual : pricing.monthly;
    const customerId = await getOrCreateStripeCustomer(
      Number(userId),
      user.email,
      user.username
    );
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      customer: customerId,
      payment_intent_data: {
        setup_future_usage: "off_session"
      },
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: `Verso Air \u2014 ${pricing.name} (${billingCycle})`,
              description: `Business directory ${pricing.name} tier subscription`
            },
            unit_amount: amount
          },
          quantity: 1
        }
      ],
      metadata: {
        userId: String(userId),
        targetTier,
        billingCycle,
        type: "subscription_fee"
      },
      success_url: `${req.headers.origin || "http://localhost:5003"}/pricing?status=success&tier=${targetTier}`,
      cancel_url: `${req.headers.origin || "http://localhost:5003"}/pricing?status=cancelled`
    });
    res.json({
      success: true,
      data: {
        sessionId: session.id,
        url: session.url
      }
    });
  } catch (error) {
    console.error("\u274C Stripe checkout error:", error);
    res.status(500).json({ success: false, error: error.message });
  }
});
