router23.post(
  "/tsr/whitelist",
  requireAuth(["admin", "superuser"]),
  asyncHandler(async (req, res) => {
    const { email } = req.body;
    if (!email || typeof email !== "string") {
      res.status(400).json({ success: false, message: "Email is required" });
      return;
    }
    const normalizedEmail = email.toLowerCase().trim();
    const existing = await db.execute(
      sql7`SELECT id, is_active FROM tsr_whitelist WHERE email = ${normalizedEmail} LIMIT 1`
    );
    if (existing.rows?.length) {
      const entry = existing.rows[0];
      if (entry.is_active) {
        res.status(409).json({ success: false, message: "Email already whitelisted" });
        return;
      }
      await db.execute(
        sql7`UPDATE tsr_whitelist SET is_active = true, granted_by = ${req.user.userId}, granted_at = NOW()
            WHERE id = ${entry.id}`
      );
      res.json({
        success: true,
        message: "TSR whitelist entry re-activated",
        reactivated: true
      });
      return;
    }
    await db.insert(tsrWhitelist).values({
      email: normalizedEmail,
      grantedBy: req.user.userId
    });
    res.json({ success: true, message: "Email added to TSR whitelist" });
  })
);
