router27.get("/stats/summary", async (req, res) => {
  try {
    const exists = await ensureTicketsTable();
    if (exists) {
      try {
        const statsRows = await db.execute(
          sql10`SELECT 
                COUNT(*) as total,
                SUM(CASE WHEN status='open' THEN 1 ELSE 0 END) as open,
                SUM(CASE WHEN status='in-progress' THEN 1 ELSE 0 END) as in_progress,
                SUM(CASE WHEN status='resolved' THEN 1 ELSE 0 END) as resolved,
                SUM(CASE WHEN status='closed' THEN 1 ELSE 0 END) as closed,
                SUM(CASE WHEN sla_breached=true THEN 1 ELSE 0 END) as sla_breaches
              FROM tickets`
        );
        const stats = statsRows.rows[0];
        const total2 = parseInt(stats?.total || "0");
        const slaBreaches2 = parseInt(stats?.sla_breaches || "0");
        const slaCompliance = total2 > 0 ? Math.round((total2 - slaBreaches2) / total2 * 100) : 100;
        return res.json({
          total: total2,
          open: parseInt(stats?.open || "0"),
          inProgress: parseInt(stats?.in_progress || "0"),
          resolved: parseInt(stats?.resolved || "0"),
          closed: parseInt(stats?.closed || "0"),
          slaBreaches: slaBreaches2,
          avgResolutionTime: 24,
          slaCompliance
        });
      } catch (dbError) {
        console.error("\u274C Database stats error:", dbError);
      }
    }
    const total = inMemoryTickets.length;
    const slaBreaches = inMemoryTickets.filter((t) => t.sla_breached).length;
    res.json({
      total,
      open: inMemoryTickets.filter((t) => t.status === "open").length,
      inProgress: inMemoryTickets.filter((t) => t.status === "in-progress").length,
      resolved: inMemoryTickets.filter((t) => t.status === "resolved").length,
      closed: inMemoryTickets.filter((t) => t.status === "closed").length,
      slaBreaches,
      avgResolutionTime: 24,
      slaCompliance: total > 0 ? Math.round((total - slaBreaches) / total * 100) : 100
    });
  } catch (error) {
    console.error("\u274C Get ticket stats failed:", error);
    res.status(500).json({ success: false, error: error.message });
  }
});
