        guaranteedAmount: parseFloat(r.guaranteed_amount) || 0,
        performanceAmount: parseFloat(r.performance_amount) || 0,
        streamCount: parseInt(r.stream_count) || 0,
        globalRank: r.global_rank,
        regionalRank: r.regional_rank,
