async function chat(messages, userRole) {
  const lastUserMsg = [...messages].reverse().find((m) => m.role === "user")?.content ?? "";
  let ctx;
  try {
    ctx = await buildAIContext(lastUserMsg, userRole);
  } catch (err) {
    console.warn("[VersoAI] Context build failed, using empty context:", err);
    ctx = {
      totalBusinesses: 0,
      activeBusinesses: 0,
      categories: [],
      countries: []
    };
  }
  const sources = extractSources(ctx);
  const systemMessage = {
    role: "system",
    content: SYSTEM_PROMPT + "\n\n" + formatContext(ctx)
  };
  const llmMessages = [systemMessage, ...messages.slice(-12)];
  try {
    const reply2 = await callOllama(llmMessages);
    console.log("[VersoAI] Ollama responded successfully");
    return {
      reply: reply2,
      provider: "ollama",
      sources,
      searchMethod: ctx.searchMethod
    };
  } catch (err) {
    console.warn("[VersoAI] Ollama unavailable:", err?.message ?? err);
  }
  if (GROQ_API_KEY) {
    try {
      const reply2 = await callGroq(llmMessages);
      console.log("[VersoAI] Groq responded successfully");
      return {
        reply: reply2,
        provider: "groq",
        sources,
        searchMethod: ctx.searchMethod
      };
    } catch (err) {
      console.warn("[VersoAI] Groq unavailable:", err?.message ?? err);
    }
  }
  const reply = smartFallback(lastUserMsg, ctx, messages);
  return {
    reply,
    provider: "fallback",
    sources,
    searchMethod: ctx.searchMethod
  };
}
async function groundedChat(question, userRole) {
  const {
    results,
    sources: rawSources,
    searchMethod
  } = await groundedSearch(question, userRole);
  const sources = rawSources.map((s) => ({
    name: s.name,
    snippet: s.snippet
  }));
  const context = results.map(
    (r) => `[${r.name}] (${r.location || r.country}, ${r.category}): ${r.description}` + (r.rating != null ? ` | Rating: \u2605${r.rating.toFixed(1)}` : "")
  ).join("\n");
  const groundedPrompt = `You are VersoAI, the business intelligence assistant for Verso Air.

Answer the user's question ONLY using the provided context below.
If the context doesn't contain enough information, say "I don't have enough data in our database to answer that precisely."
NEVER invent or fabricate information. Cite businesses by name when referencing them.

CONTEXT (from Verso Air database \u2014 ${results.length} results via ${searchMethod} search):
${context || "No matching records found in the database."}

QUESTION: ${question}

ANSWER (be specific, cite sources by name):`;
  const groundedMessages = [
    { role: "system", content: groundedPrompt },
    { role: "user", content: question }
  ];
  try {
    const reply = await callOllama(groundedMessages);
    return {
      answer: reply,
      sources,
      searchMethod,
      confidence: results.length > 0 ? 0.9 : 0.2
    };
  } catch {
  }
  if (GROQ_API_KEY) {
    try {
      const reply = await callGroq(groundedMessages);
      return {
        answer: reply,
        sources,
        searchMethod,
        confidence: results.length > 0 ? 0.85 : 0.2
      };
    } catch {
    }
  }
  {
    if (results.length === 0) {
      return {
        answer: "I searched the database but couldn't find matching records for your question. Try rephrasing or asking about a specific sector or country.",
        sources: [],
        searchMethod,
        confidence: 0.1
      };
    }
    const formattedList = results.map((r, i) => {
      const rating = r.rating != null ? ` \u2605${r.rating.toFixed(1)}` : "";
      return `${i + 1}. **${r.name}** \u2014 ${r.category} | ${r.location || r.country}${rating}${r.description ? `
   ${r.description}` : ""}`;
    }).join("\n");
    return {
      answer: `Here's what I found in the database for your question:

${formattedList}

\u{1F4CC} These results are grounded in our live database \u2014 no AI-generated data.`,
      sources,
      searchMethod,
      confidence: results.length >= 3 ? 0.8 : 0.5
    };
  }
}

