        urgency: aiResult.urgency ?? ruleResult.urgency,
        location: aiResult.location ?? ruleResult.location,
        countryCode: aiResult.countryCode ?? ruleResult.countryCode,
        action: aiResult.action ?? ruleResult.action,
        keywords: aiResult.keywords?.length ? aiResult.keywords : ruleResult.keywords,
        language: ruleResult.language,
        // rule-based is fine for this
        confidence: Math.min(1, ruleResult.confidence + 0.3),
        // AI boosts confidence
