// server/utils/artist-code-generator.ts
function nameToCode(stageName) {
  const clean = stageName.replace(/[^a-zA-Z]/g, "").toUpperCase();
  if (clean.length <= 2) return clean || "XX";
  const consonants = clean.replace(/[AEIOU]/g, "");
  if (consonants.length >= 2) return consonants.slice(0, 2);
  return clean[0] + clean[clean.length - 1];
}
function rankToLetter(rank) {
  const map = {
    rookie: "R",
    pro: "P",
    elite: "E",
    legend: "L",
    platinum: "X"
  };
  return map[rank] || "R";
}
function generateARC(input) {
  const type = { solo: "S", group: "G", composer: "C" };
  const verify = {
    verified: "V",
    unverified: "U",
    premium: "P"
  };
  const rights = {
    full: "F",
    licensed: "L",
    emerging: "E"
  };
  return (type[input.accountType || "solo"] || "S") + (verify[input.verification || "unverified"] || "U") + (rights[input.rights || "emerging"] || "E");
}
function generateMOD(input) {
  const genre = {
    mainstream: "M",
    indie: "I",
    orchestral: "O"
  };
  const engage = { active: "A", dormant: "D" };
  const money = { paid: "P", royalty_free: "R" };
  return (genre[input.genreClass || "indie"] || "I") + (engage[input.engagement || "active"] || "A") + (money[input.monetization || "royalty_free"] || "R");
}
function generateTAG(input) {
  const etype = {
    artist: "A",
    label: "L",
    podcaster: "P"
  };
  const auth = {
    independent: "I",
    signed: "S",
    managed: "M"
  };
  const grade = { bronze: "B", silver: "S", gold: "G" };
  return (etype[input.entityType || "artist"] || "A") + (auth[input.authority || "independent"] || "I") + (grade[input.grade || "bronze"] || "B");
}
function generateArtistCode2(input) {
  const name = nameToCode(input.stageName);
  const rank = rankToLetter(input.rank || "rookie");
  const arc = generateARC(input);
  const mod = generateMOD(input);
  const tag = generateTAG(input);
  const country = input.countryCode || "000";
  const last = (input.lastName?.[0] || "x").toLowerCase();
  return `VA_${name}-${rank}_${arc}-${mod}-${tag}-${country}.${last}`;
}
function scoreToRank(score) {
  if (score >= 9.5) return "platinum";
  if (score >= 8.5) return "legend";
  if (score >= 7) return "elite";
  if (score >= 5) return "pro";
  return "rookie";
}
function streamsToGrade(streams) {
  if (streams >= 1e6) return "gold";
  if (streams >= 1e4) return "silver";
  return "bronze";
}
