router44.get("/methods", async (_req, res) => {
  let interacEnabled = false;
  let cryptoEnabled = false;
  let mobileMoneyEnabled = false;
  try {
    const settings = await pool.query(
      `SELECT setting_key, setting_value FROM platform_settings
       WHERE setting_key IN ('payment_interac_enabled', 'payment_crypto_enabled', 'payment_mobile_money_enabled')`
    );
    for (const row of settings.rows) {
      const val = row.setting_value === true || row.setting_value === "true";
      if (row.setting_key === "payment_interac_enabled") interacEnabled = val;
      if (row.setting_key === "payment_crypto_enabled") cryptoEnabled = val;
      if (row.setting_key === "payment_mobile_money_enabled")
        mobileMoneyEnabled = val;
    }
  } catch {
  }
  const methods = PAYMENT_METHODS.map((m) => {
    if (m.id === "crypto")
      return {
        ...m,
        status: cryptoEnabled ? "active" : "coming_soon",
        availableSoon: !cryptoEnabled
      };
    if (m.id === "mobile_money")
      return {
        ...m,
        status: mobileMoneyEnabled ? "active" : "coming_soon",
        availableSoon: !mobileMoneyEnabled
      };
    return m;
  });
  if (interacEnabled) {
    methods.splice(2, 0, {
      id: "interac",
      name: "Interac e-Transfer",
      nameFr: "Virement Interac",
      description: "Send and receive money via Interac e-Transfer \u2014 Canada's leading payment method",
      descriptionFr: "Envoyez et recevez de l'argent via Interac \u2014 le mode de paiement #1 au Canada",
      icon: "\u{1F341}",
      status: "active",
      availableSoon: false,
      minDeposit: 5,
      minWithdrawal: 10,
      fees: { deposit: 0, withdrawal: 1.5 },
      currencies: ["CAD"]
    });
  }
  res.json({ success: true, methods });
});
