router60.put(
  "/products/:id",
  requireAuth(),
  async (req, res) => {
    try {
      const userId = Number(req.user?.userId);
      const productId = parseInt(req.params.id);
      if (isNaN(productId))
        return res.status(400).json({ error: "Invalid product ID" });
      const check = await pool.query(
        "SELECT id FROM inventory_products WHERE id = $1 AND user_id = $2",
        [productId, userId]
      );
      if (!check.rows.length)
        return res.status(404).json({ error: "Product not found" });
      const updates = req.body;
      const setFields = [];
      const params = [];
      let idx = 1;
      const allowedFields = {
        name: "name",
        sku: "sku",
        category: "category",
        currentStock: "current_stock",
        reorderPoint: "reorder_point",
        reorderQuantity: "reorder_quantity",
        unitCost: "unit_cost",
        unitPrice: "unit_price",
        supplier: "supplier",
        warehouseLocation: "warehouse_location",
        dailySalesRate: "daily_sales_rate",
        lastRestocked: "last_restocked",
        status: "status",
        businessId: "business_id",
        sector: "sector"
      };
      for (const [camel, snake] of Object.entries(allowedFields)) {
        if (updates[camel] !== void 0) {
          setFields.push(`${snake} = $${idx}`);
          params.push(updates[camel]);
          idx++;
        }
      }
      if (!setFields.length)
        return res.status(400).json({ error: "No fields to update" });
      setFields.push(`updated_at = NOW()`);
      params.push(productId, userId);
      const result = await pool.query(
        `UPDATE inventory_products SET ${setFields.join(", ")}
       WHERE id = $${idx} AND user_id = $${idx + 1}
       RETURNING *`,
        params
      );
      res.json({ product: result.rows[0] });
    } catch (err) {
      console.error("[Inventory] Update error:", err.message);
      res.status(500).json({ error: "Failed to update product" });
    }
  }
);
