router62.post(
  "/request",
  requireAuth(),
  asyncHandler(async (req, res) => {
    const userId = req.user.userId;
    const access = await getGeoAccessLevel(userId);
    if (access.level === "none") {
      res.status(403).json({
        success: false,
        message: "You do not have geo-admin access. Upgrade to Max or Enterprise tier."
      });
      return;
    }
    const { actionType, entityType, entityId, requestedChange } = req.body;
    if (!actionType || !entityType || !entityId) {
      res.status(400).json({
        success: false,
        message: "actionType, entityType, and entityId are required"
      });
      return;
    }
    const validActions = ["create", "edit", "delete"];
    if (!validActions.includes(actionType)) {
      res.status(400).json({
        success: false,
        message: `actionType must be one of: ${validActions.join(", ")}`
      });
      return;
    }
    if (!access.requiresQueue) {
      const [inserted2] = await db.insert(geoActionRequests).values({
        requestedBy: userId,
        actionType,
        entityType,
        entityId: String(entityId),
        requestedChange: requestedChange || null,
        delayHours: 0,
        status: "approved",
        reviewedBy: userId,
        reviewedAt: /* @__PURE__ */ new Date(),
        reviewNotes: "Auto-approved (staff)",
        expiresAt: null
      }).returning();
      res.json({
        success: true,
        message: "Action approved immediately (staff access)",
        request: inserted2,
        autoApproved: true
      });
      return;
    }
    const delayHours = actionType === "delete" ? access.deleteDelayHours : actionType === "edit" ? access.editDelayHours : 0;
    const expiresAt = new Date(Date.now() + delayHours * 60 * 60 * 1e3);
    const [inserted] = await db.insert(geoActionRequests).values({
      requestedBy: userId,
      actionType,
      entityType,
      entityId: String(entityId),
      requestedChange: requestedChange || null,
      delayHours,
      status: "pending",
      expiresAt
    }).returning();
    res.json({
      success: true,
      message: `Request queued. ${actionType === "delete" ? "Delete requests require admin approval (72h window)." : `Edit will be auto-approved after ${delayHours}h delay.`}`,
      request: inserted,
      autoApproved: false,
      delayHours,
      expiresAt
    });
  })
);
