// server/utils/logger.ts
var LEVELS = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3
};
function currentLevel() {
  const env = process.env.LOG_LEVEL;
  if (env && env in LEVELS) return LEVELS[env];
  return process.env.NODE_ENV === "production" ? LEVELS.info : LEVELS.debug;
}
function timestamp3() {
  return (/* @__PURE__ */ new Date()).toISOString();
}
function format(level, context, message) {
  return `${timestamp3()} [${level.toUpperCase()}] [${context}] ${message}`;
}
function shouldLog(level) {
  return LEVELS[level] >= currentLevel();
}
function createLogger(context) {
  return {
    debug(message, ...args) {
      if (shouldLog("debug")) console.debug(format("debug", context, message), ...args);
    },
    info(message, ...args) {
      if (shouldLog("info")) console.info(format("info", context, message), ...args);
    },
    warn(message, ...args) {
      if (shouldLog("warn")) console.warn(format("warn", context, message), ...args);
    },
    error(message, ...args) {
      if (shouldLog("error")) console.error(format("error", context, message), ...args);
    }
  };
}
var logger = createLogger("app");

// server/services/digest-worker.ts
init_db();
init_schema();
init_email_service();
import { eq as eq39, and as and24, sql as sql29, inArray as inArray2 } from "drizzle-orm";
var DIGEST_CHECK_INTERVAL_MS = 60 * 60 * 1e3;
var MAX_RETRIES = 3;
var BATCH_SIZE = 50;
var DAILY_DIGEST_HOUR = 8;
var WEEKLY_DIGEST_DAY = 1;
var digestInterval = null;
function startDigestWorker() {
  console.log("[DIGEST] \u{1F4EE} Starting digest worker...");
  setTimeout(() => {
    processDigestQueue().catch(
      (err) => console.error("[DIGEST] Initial run error:", err)
    );
  }, 5e3);
  digestInterval = setInterval(() => {
    processDigestQueue().catch(
      (err) => console.error("[DIGEST] Scheduled run error:", err)
    );
  }, DIGEST_CHECK_INTERVAL_MS);
  console.log(
    `[DIGEST] Worker scheduled every ${DIGEST_CHECK_INTERVAL_MS / 6e4} minutes`
  );
}
async function processDigestQueue() {
  const now = /* @__PURE__ */ new Date();
  const hour = now.getHours();
  const dayOfWeek = now.getDay();
  console.log(
    `[DIGEST] Processing queue at ${now.toISOString()} (hour=${hour}, day=${dayOfWeek})`
  );
  await retryFailedItems();
  if (hour === DAILY_DIGEST_HOUR) {
    await processDailyDigests();
  }
  if (dayOfWeek === WEEKLY_DIGEST_DAY && hour === DAILY_DIGEST_HOUR) {
    await processWeeklyDigests();
    await processGeoAdminReports();
  }
}
async function processDailyDigests() {
  console.log("[DIGEST] Processing daily digests...");
  try {
    const pendingItems = await db.select({
      queueItem: emailQueue,
      subscriptionFrequency: emailSubscriptions.frequency,
      unsubscribeToken: emailSubscriptions.unsubscribeToken,
      recipientName: users.username
    }).from(emailQueue).innerJoin(
      emailSubscriptions,
      eq39(emailQueue.subscriptionId, emailSubscriptions.id)
    ).innerJoin(users, eq39(emailQueue.recipientUserId, users.id)).where(
      and24(
        eq39(emailQueue.status, "pending"),
        eq39(emailSubscriptions.frequency, "daily_digest"),
        eq39(emailSubscriptions.isActive, true)
      )
    ).limit(BATCH_SIZE);
    if (pendingItems.length === 0) {
      console.log("[DIGEST] No daily digest items to process");
      return;
    }
    const grouped = groupByRecipient(pendingItems);
    let sent = 0;
    for (const [recipientEmail, items] of Object.entries(grouped)) {
      try {
        const success = await sendDigestEmail(recipientEmail, items, "daily");
        const status = success ? "sent" : "failed";
        const queueIds = items.map((i) => i.queueItem.id);
        await db.update(emailQueue).set({
          status,
          sentAt: success ? /* @__PURE__ */ new Date() : void 0,
          error: success ? void 0 : "Digest send failed"
        }).where(inArray2(emailQueue.id, queueIds));
        if (success) sent++;
      } catch (err) {
        console.error(
          `[DIGEST] Failed to send daily digest to ${recipientEmail}:`,
          err
        );
      }
    }
    console.log(
      `[DIGEST] Daily digests: ${sent}/${Object.keys(grouped).length} sent`
    );
  } catch (error) {
    console.error("[DIGEST] Error processing daily digests:", error);
  }
}
