// server/services/newsletter-cron.ts
init_db();
import cron4 from "node-cron";
function setupNewsletterCron() {
  cron4.schedule("5 * * * *", async () => {
    try {
      const dueCampaigns = await pool.query(
        `SELECT * FROM newsletter_campaigns
         WHERE status = 'scheduled' AND scheduled_at <= NOW()
         ORDER BY scheduled_at ASC`
      );
      if (dueCampaigns.rows.length === 0) return;
      for (const campaign of dueCampaigns.rows) {
        console.log(
          `[NEWSLETTER-CRON] Sending campaign: "${campaign.title}" (ID: ${campaign.id})`
        );
        await pool.query(
          `UPDATE newsletter_campaigns SET status = 'sending', updated_at = NOW() WHERE id = $1`,
          [campaign.id]
        );
        const subscribers = await pool.query(
          `SELECT email, name FROM newsletter_subscribers WHERE is_active = true`
        );
        let queued = 0;
        for (const sub of subscribers.rows) {
          await pool.query(
            `INSERT INTO email_queue (recipient_email, subject, html_body, email_type, status)
             VALUES ($1, $2, $3, 'newsletter', 'pending')`,
            [
              sub.email,
              campaign.subject || campaign.title,
              campaign.content || `<p>${campaign.title}</p>`
            ]
          );
          queued++;
        }
        await pool.query(
          `UPDATE newsletter_campaigns SET status = 'sent', sent_at = NOW(), recipient_count = $1, updated_at = NOW() WHERE id = $2`,
          [queued, campaign.id]
        );
        console.log(
          `[NEWSLETTER-CRON] Campaign "${campaign.title}" sent to ${queued} subscribers`
        );
      }
    } catch (error) {
      console.error("[NEWSLETTER-CRON] Error processing campaigns:", error);
    }
  });
  console.log("\u{1F4E7} [NEWSLETTER-CRON] Scheduled: hourly campaign check");
}

// server/services/marketplace-auto-approve.ts
init_db();
async function autoApproveStalePendingListings() {
  try {
    const result = await pool.query(
      `UPDATE ad_journal_listings 
       SET status = 'active', updated_at = NOW() 
       WHERE status = 'pending' 
         AND created_at < NOW() - INTERVAL '24 hours'
       RETURNING id, title`
    );
    const approvedCount = result.rowCount || 0;
    if (approvedCount > 0) {
      console.log(
        `[MARKETPLACE-CRON] Auto-approved ${approvedCount} pending listings after 24h:`,
        result.rows.map((r) => `#${r.id} "${r.title}"`).join(", ")
      );
    }
    return approvedCount;
  } catch (error) {
    console.error("[MARKETPLACE-CRON] Auto-approve error:", error.message);
    return 0;
  }
}
function setupMarketplaceAutoApprove() {
  autoApproveStalePendingListings().then((count11) => {
    if (count11 > 0) {
      console.log(
        `[MARKETPLACE-CRON] Startup: Auto-approved ${count11} stale listings`
      );
    }
  });
  const ONE_HOUR = 60 * 60 * 1e3;
  setInterval(async () => {
    await autoApproveStalePendingListings();
  }, ONE_HOUR);
  console.log(
    "[MARKETPLACE-CRON] Auto-approve scheduler initialized (checks hourly, approves after 24h)"
  );
}

